function createMatrixCascadeEngine(canvas) {
    const ctx = canvas.getContext('2d');
    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;
    const resizeHandler = ()=>{
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resizeHandler);
    const layers = [
        {
            count: Math.floor(width / 34),
            fontSize: 11,
            speedMin: 3,
            speedMax: 5,
            alpha: 0.35
        },
        {
            count: Math.floor(width / 24),
            fontSize: 15,
            speedMin: 6,
            speedMax: 10,
            alpha: 0.65
        },
        {
            count: Math.floor(width / 18),
            fontSize: 22,
            speedMin: 12,
            speedMax: 18,
            alpha: 0.95
        }
    ];
    const columns = [];
    layers.forEach((layer, layerIdx)=>{
        for(let i = 0; i < layer.count; i++){
            columns.push({
                x: Math.random() * width,
                y: Math.random() * -height,
                speed: layer.speedMin + Math.random() * (layer.speedMax - layer.speedMin),
                fontSize: layer.fontSize,
                alpha: layer.alpha,
                layerIdx,
                chars: Array.from({
                    length: 24
                }, ()=>Math.random() > 0.5 ? '1' : '0')
            });
        }
    });
    let converging = false;
    let animId;
    function render() {
        ctx.fillStyle = 'rgba(2, 2, 6, 0.22)';
        ctx.fillRect(0, 0, width, height);
        columns.forEach((col)=>{
            // Live dynamic character flipping between 0 and 1
            if (Math.random() < 0.35) {
                const flipIdx = Math.floor(Math.random() * col.chars.length);
                col.chars[flipIdx] = Math.random() > 0.5 ? '1' : '0';
            }
            if (converging) {
                col.x += (width / 2 - col.x) * 0.04;
                col.y += (height / 2 - col.y) * 0.04;
            } else {
                col.y += col.speed;
                if (col.y > height + 240) {
                    col.y = -Math.random() * 200;
                    col.x = Math.random() * width;
                }
            }
            ctx.font = `${col.fontSize}px 'JetBrains Mono', monospace`;
            for(let j = 0; j < col.chars.length; j++){
                const charY = col.y - j * col.fontSize;
                if (charY < 0 || charY > height) continue;
                if (j === 0) {
                    // Luminous Leading Head
                    ctx.fillStyle = '#FFFFFF';
                    ctx.shadowColor = '#00FF88';
                    ctx.shadowBlur = 14;
                } else if (j < 4) {
                    ctx.fillStyle = `rgba(0, 255, 136, ${col.alpha})`;
                    ctx.shadowColor = '#00FF88';
                    ctx.shadowBlur = 6;
                } else {
                    ctx.fillStyle = `rgba(0, 229, 255, ${col.alpha * (1 - j / col.chars.length)})`;
                    ctx.shadowBlur = 0;
                }
                ctx.fillText(col.chars[j], col.x, charY);
            }
        });
        animId = requestAnimationFrame(render);
    }
    render();
    return {
        setConverging: (val)=>{
            converging = val;
        },
        stop: ()=>{
            cancelAnimationFrame(animId);
            window.removeEventListener('resize', resizeHandler);
        }
    };
}
